};

export const setFeatureFlags = (featureCode: string, value: boolean) => {
    featureFlags[featureCode] = {
        ...defaultFeatureFlagValue,
        Code: featureCode,
        Value: value,
    };
};

export const clearFeatureFlags = () => {
    Object.keys(featureFlags).forEach((key) => delete apiMocks[key]);
};

